{"code": "// Real fix: an already-decided event must still complete its job and return the decision.
const e1 = await tools.edit({
  file_path: "triage.py",
  old_string: `        if await self.store.get_decision_for_event(event_id) is not None:
            logger.info("event %s already has a decision; skipping", event_id)
            return None`,
  new_string: `        existing = await self.store.get_decision_for_event(event_id)
        if existing is not None:
            # Idempotent re-entry: a lease expired while the first worker was still writing, or
            # an operator replayed the job. Return the decision that exists *and* close this
            # job, otherwise a reclaimed job would spin until its attempts ran out.
            logger.info("event %s already has decision %s", event_id, existing.decision_id)
            if job is not None:
                await self.store.complete_job(job.job_id)
            return existing`,
});

// Wrong expectation: 90 min against a 60 min allowance is 30 min over -> 1 started hour -> 100.00.
const e2 = await tools.edit({
  file_path: "tests/test_triage.py",
  old_string: `    assert payload["computed_by_service"]["estimated_penalty"] == "50.00"`,
  new_string: `    # 90 min reported against a 60 min allowance: 30 min over, billed as one started hour.
    assert payload["computed_by_service"]["excess_minutes"] == 30
    assert payload["computed_by_service"]["estimated_penalty"] == "100.00"`,
});

const r = await tools.bash({
  command: `.venv/bin/python -m pytest 2>&1 | tail -20`,
  description: 'Run full test suite',
  timeoutMs: 300000
});
console.log("patched triage.py + test_triage.py");
if (r.kind === 'foreground') console.log(r.stdout.text, r.stderr.text, '[exit]', r.exitCode);
", "description": "Fix idempotency gap and re-run all tests"}

