import asyncio, json, httpx, sys
sys.path.insert(0, ".")
import instructor
from openai import AsyncOpenAI
from schemas import TriageProposal

SEEN = []
def handler(request):
    body = json.loads(request.content)
    SEEN.append(body)
    p = {"severity":"LOW","action":"NO_ACTION","confidence_score":0.9,"email_draft":None,
         "escalation_reason":None,"reasoning_summary":"m","signals":[],"flags":[]}
    if body.get("tools"):
        msg = {"role":"assistant","content":None,
               "tool_calls":[{"id":"c1","type":"function",
                              "function":{"name":"TriageProposal","arguments":json.dumps(p)}}]}
        finish = "tool_calls"
    else:
        msg, finish = {"role":"assistant","content":json.dumps(p)}, "stop"
    return httpx.Response(200, json={"id":"c","object":"chat.completion","created":0,"model":"m",
        "choices":[{"index":0,"finish_reason":finish,"message":msg}],
        "usage":{"prompt_tokens":1,"completion_tokens":1,"total_tokens":2}})

async def main():
    client = AsyncOpenAI(api_key="k", base_url="https://api.openai.com/v1", max_retries=0,
                         http_client=httpx.AsyncClient(transport=httpx.MockTransport(handler)))
    for mode in (instructor.Mode.JSON_SCHEMA, instructor.Mode.TOOLS_STRICT, instructor.Mode.TOOLS):
        SEEN.clear()
        ins = instructor.from_openai(client, mode=mode)
        try:
            r = await ins.chat.completions.create(model="m", messages=[{"role":"user","content":"hi"}],
                                                  response_model=TriageProposal, max_retries=0)
        except Exception as exc:
            print(f"--- {mode.name}: FAILED {type(exc).__name__}"); continue
        b = SEEN[0]
        print(f"--- {mode.name}: parsed {r.action.value} ---")
        if "tools" in b:
            fn = b["tools"][0]["function"]
            params = fn["parameters"]
            def deep_ok(node):
                if isinstance(node, dict):
                    if "properties" in node:
                        if set(node.get("required", [])) != set(node["properties"]): return False
                        if node.get("additionalProperties") is not False: return False
                    return all(deep_ok(v) for v in node.values())
                if isinstance(node, list): return all(deep_ok(i) for i in node)
                return True
            print("   tools[0].strict          =", b["tools"][0].get("strict"))
            print("   schema fully tightened   =", deep_ok(params))
            print("   EmailDraft strict        =", params.get("$defs",{}).get("EmailDraft",{}).get("additionalProperties"))
        if "response_format" in b:
            rf = b["response_format"]
            print("   response_format.strict   =", rf["json_schema"].get("strict"))

asyncio.run(main())
