    interesting = (*RETRYABLE_API_ERRORS, *TERMINAL_API_ERRORS, ValidationError)
    seen: set[int] = set()
    current: BaseException | None = exc
    while current is not None and id(current) not in seen:
        seen.add(id(current))
        if isinstance(current, interesting):
