                async with asyncio.timeout(self._timeout + 5.0):
                    completion = await raw_client.chat.completions.parse(
                        model=spec.model,
                        messages=conversation,
                        response_format=TriageProposal,
                        temperature=0.0,
                        timeout=self._timeout,
                    )
