const r = await tools.bash({
  command: `set -e
cd "$PWD"
echo "=== 1. run_live.py with no credentials (should give instructions, exit 2) ==="
env -u DEEPSEEK_API_KEY -u OPENAI_API_KEY .venv/bin/python run_live.py; echo "exit=$?"

echo
