kill -TERM $MOCK_PID 2>/dev/null || true
trap - EXIT`,
  description: 'Verify run_live against a local provider',
  timeoutMs: 300000
});
console.log("wrote", w.path, "| patched run_live.py");
if (r.kind === 'foreground') console.log(r.stdout.text, r.stderr.text, '[exit]', r.exitCode);
", "description": "Verify run_live against a compromised mock provider"}

